using CustomCodeFramework.Core.Results;using CustomCodeFramework.Cqrs.Commands;using CustomCodeFramework.Persistence.Abstractions;using Dhole.Content.Application.Abstractions.Auditing;using Dhole.Content.Application.Abstractions.Cache;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Application.Auditing;using Dhole.Content.Domain.Shared;namespace Dhole.Content.Application.Settings.DeleteSiteSetting;public sealed class DeleteSiteSettingCommandHandler(ISiteSettingRepository repo,IContentAuditService audit,IContentCacheService cache,IUnitOfWork uow):ICommandHandler<DeleteSiteSettingCommand,Result>{public async Task<Result> HandleAsync(DeleteSiteSettingCommand c,CancellationToken ct=default){var x=await repo.GetByIdAsync(c.Id,ct);if(x is null||x.IsDeleted)return Result.Failure(ContentErrors.SettingNotFound);var before=ContentAuditSnapshots.From(x);x.Delete(c.ActorUserId);await audit.PublishAsync(new ContentAuditEvent(ContentAuditEventTypes.SettingDeleted,ContentAuditActions.Deleted,ContentAuditEntityTypes.SiteSetting,x.Id,c.ActorUserId,Before:before,After:ContentAuditSnapshots.From(x)),ct);await uow.SaveChangesAsync(ct);await cache.RemovePublicSettingsAsync(x.SiteKey,ct);return Result.Success();}}
